<script setup lang="ts">
import PageHeading from '../components/PageHeading.vue';
import EntitlementDialog from '../components/EntitlementDialog.vue';
import '../styles/admin-ui.css';
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import GroupNodeList from '../components/GroupNodeList.vue';
import {filterGroupMembers} from '../lib/nodeGroups';
import {Package,Layers3,Plus,Pencil,RefreshCw,X,Search,Trash2,ArrowUpRight,CheckCircle2,ShieldCheck} from 'lucide-vue-next';
import type {Plan,NodeGroup,GroupMember,User} from '../types';
import {useApi,isCancelled} from '../lib/api';
import {latestRequest} from '../lib/requests';
import {bytes} from '../lib/format';
import {cents,money} from '../lib/commerce';
import {t} from '../i18n';
import {usePanelContext} from '../composables/panelContext';
import {useModalFocus} from '../composables/useModalFocus';
import PlanNodeSelector from '../components/PlanNodeSelector.vue';
const route=useRoute(),router=useRouter();
const props=defineProps<{mode?:'plans'|'groups'}>();
const groupSearch=ref(''),groupSource=ref('all');
const groupRows=(id:string)=>filterGroupMembers(members.value[id]||[],groupSearch.value,groupSource.value);
const {state,confirmation,refresh,showSub,selectedSite}=usePanelContext(),api=useApi();
const plans=ref<Plan[]>([]),groups=ref<NodeGroup[]>([]),members=ref<Record<string,GroupMember[]>>({}),loaded=ref(false),busy=ref(false),error=ref(''),tab=ref(props.mode|| (route.query.tab==='groups'?'groups':'plans')),search=ref(''),category=ref(''),archived=ref(false);
watch(()=>route.query.tab,value=>{if(props.mode)return;if(value==='groups'){void router.replace({path:'/node-groups',query:{...route.query,tab:undefined}});}else tab.value='plans';},{immediate:true});
const workspace=computed<'catalog'|'members'>({get:()=>route.query.workspace==='members'?'members':'catalog',set:value=>{void router.replace({query:{...route.query,workspace:value==='members'?'members':undefined,plan:value==='members'?route.query.plan:undefined}});}});
const snapshotPlan=computed({get:()=>typeof route.query.plan==='string'?route.query.plan:'',set:value=>{void router.replace({query:{...route.query,workspace:'members',plan:value||undefined}});}});
const entitlementUsers=ref<User[]>([]);
const assignedUsers=(id:string)=>(state.value?.users||[]).filter(u=>!u.mount_access&&u.entitlement?.plan_id===id);
const snapshotUsers=computed(()=>(state.value?.users||[]).filter(u=>!u.mount_access&&u.entitlement&&(!snapshotPlan.value||u.entitlement.plan_id===snapshotPlan.value)));
const currentVersion=(u:User)=>plans.value.find(p=>p.id===u.entitlement?.plan_id)?.version;
function showMembers(id=''){void router.replace({query:{...route.query,workspace:'members',plan:id||undefined}});}
async function entitlementUpdated(){entitlementUsers.value=[];await refresh();await load();}
const loading=ref(false),notice=ref(''),loadRequest=latestRequest();
const editingPlan=ref<Plan|null>(null),quotaGB=ref(0),unlimited=ref(false),priceYuan=ref('0.00'),dialog=ref<HTMLElement|null>(null);
const open=computed(()=>!!editingPlan.value),editorBaseline=ref(''),discardRequested=ref(false),discardNotice=ref<HTMLElement|null>(null);
const editorSignature=()=>JSON.stringify([editingPlan.value,quotaGB.value,unlimited.value,priceYuan.value]);
const editorDirty=computed(()=>!!editingPlan.value&&editorSignature()!==editorBaseline.value);
const categories=computed(()=>[...new Set(plans.value.map(p=>p.category).filter(Boolean))].sort());
const filtered=computed(()=>plans.value.filter(p=>(archived.value||!p.archived)&&(!category.value||p.category===category.value)&&[p.name,p.description,p.category].join(' ').toLowerCase().includes(search.value.toLowerCase())).sort((a,b)=>a.sort-b.sort||a.name.localeCompare(b.name)));
const visibleGroups=computed(()=>[...groups.value].sort((a,b)=>a.sort-b.sort||a.name.localeCompare(b.name)));
const filteredGroups=computed(()=>visibleGroups.value.filter(g=>(!groupSearch.value&&groupSource.value==='all')||groupRows(g.id).length));
const selectedNodesInGroup=(plan:Plan,groupID:string)=>{const membersInGroup=new Set((members.value[groupID]||[]).flatMap(member=>[member.selection_key,member.source==='mounted'||member.source==='business'?undefined:member.node_id]));return (plan.node_ids||[]).filter(id=>id.startsWith(groupID+'/')||membersInGroup.has(id));};
const cycleLabel=(cycle:string)=>cycle==='30d'?t('每 30 天'):cycle==='month'?t('每自然月'):t('不自动重置');
function goShop(){router.push('/shop');}
const pageTitle=computed(()=>tab.value==='groups'?t('节点组管理'):t('套餐管理'));
const pageSubtitle=computed(()=>tab.value==='groups'?t('节点按来源自动归入三个默认组，订阅权限由套餐决定。'):t('套餐统一决定账号额度、有效期和节点权限。'));
function discardPlan(){editingPlan.value=null;discardRequested.value=false;error.value='';}
async function close(){if(busy.value)return;if(editorDirty.value){discardRequested.value=true;await nextTick();discardNotice.value?.focus();discardNotice.value?.scrollIntoView({block:'nearest'});return;}discardPlan();}
useModalFocus(open,dialog,close);
async function load(){
 const request=loadRequest.start();loading.value=true;error.value='';
 try{
  const [p,g]=await Promise.all([
   api<{plans:Plan[]}>('/plans','GET',undefined,{signal:request.signal}),
   api<{groups:NodeGroup[];members:Record<string,GroupMember[]>}>('/node-groups','GET',undefined,{signal:request.signal})
  ]);
  if(!loadRequest.isCurrent(request))return;
  plans.value=p.plans;groups.value=g.groups;members.value=g.members;loaded.value=true;
 }catch(e){if(loadRequest.isCurrent(request)&&!isCancelled(e))error.value=(e as Error).message;}
 finally{if(loadRequest.isCurrent(request))loading.value=false;}
}
function editPlan(p?:Plan){discardRequested.value=false;error.value='';editingPlan.value=p?JSON.parse(JSON.stringify({...p,node_ids:p.node_ids||[]})):{id:'',version:0,name:'',description:'',category:'',notes:'',archived:false,sort:0,quota:100*1024**3,valid_days:30,cycle:'30d',timezone:'Asia/Shanghai',group_ids:[],node_ids:[],vless:true,hy2:true,price:'0',system:false};quotaGB.value=editingPlan.value!.quota/1024**3;unlimited.value=!editingPlan.value!.quota;priceYuan.value=(Number(editingPlan.value!.price||'0')/100).toFixed(2);editorBaseline.value=editorSignature();}
async function save(){if(busy.value)return;loadRequest.cancel();loading.value=false;busy.value=true;error.value='';try{if(editingPlan.value){const price=priceYuan.value.trim()==='0'||priceYuan.value.trim()==='0.0'||priceYuan.value.trim()==='0.00'?'0':cents(priceYuan.value);const p={...editingPlan.value,price,quota:unlimited.value?0:Math.round(quotaGB.value*1024**3)};if(!unlimited.value&&p.quota<=0)throw new Error(t('有限额度必须大于 0'));await api('/plans','POST',p);}editingPlan.value=null;notice.value=t('套餐设置已保存，当前成员订阅会立即同步');await refresh();await load();}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{busy.value=false;}}
function deletePlan(p:Plan){confirmation.value={title:t('删除套餐')+' · '+p.name,detail:p.system?t('系统预置套餐不能删除。'):t('删除会立即移除套餐、版本和商品引用；已有用户权益与订单快照不会回滚。'),action:async()=>{await api('/plans/'+encodeURIComponent(p.id),'DELETE');notice.value=t('套餐已删除');await load();}};}
onMounted(load);
onUnmounted(()=>loadRequest.cancel());
</script>
<template>
<section class="plans-page admin-page">
 <PageHeading :title="pageTitle" :description="pageSubtitle" :eyebrow="tab==='groups'?'RESOURCE GROUPS':'PLAN WORKSPACE'"><template #actions><button :disabled="busy||loading" @click="load"><RefreshCw :size="16" :class="{spin:loading}"/>{{t('刷新')}}</button><button v-if="tab==='plans'" class="primary" @click="editPlan()"><Plus :size="16"/>{{t('创建套餐')}}</button></template></PageHeading>
 <p v-if="notice" class="plan-notice" role="status"><CheckCircle2 :size="17"/><span>{{notice}}</span><button class="icon" :aria-label="t('关闭')" @click="notice=''"><X :size="16"/></button></p>
 <nav v-if="tab==='plans'" class="admin-workspace-tabs" :aria-label="t('套餐工作区')"><button :aria-pressed="workspace==='catalog'" @click="workspace='catalog'"><Package :size="17"/>{{t('套餐内容')}}<span>{{plans.filter(p=>!p.archived).length}}</span></button><button v-if="!selectedSite" @click="goShop"><ArrowUpRight :size="16"/>{{t('销售配置')}}</button><button :aria-pressed="workspace==='members'" @click="showMembers()"><ShieldCheck :size="17"/>{{t('成员生效权益')}}<span>{{(state?.users||[]).filter(u=>!u.mount_access&&u.entitlement).length}}</span></button></nav>
 <div v-if="tab==='plans'" class="admin-context-strip"><ShieldCheck :size="18"/><div><strong>{{t(workspace==='catalog'?'套餐内容是授权模板':'这里展示成员当前实际生效的权益')}}</strong><p>{{t(workspace==='catalog'?'保存后会立即同步当前生效成员；额度、到期时间和排队套餐快照保持不变。':'这里会实时显示套餐节点权限；成员的流量额度与到期时间保持不变。')}}</p></div><button v-if="workspace==='catalog'" @click="showMembers()">{{t('查看生效情况')}}<ArrowUpRight :size="15"/></button></div>
 <p v-if="error&&!open" class="error" role="alert">{{t(error)}}</p>
 <template v-if="tab==='plans'&&workspace==='catalog'"><div class="toolbar"><div class="search"><Search :size="16"/><input v-model="search" :placeholder="t('搜索套餐')" :aria-label="t('搜索套餐')"/></div><select v-model="category" :aria-label="t('套餐分类')"><option value="">{{t('全部分类')}}</option><option v-for="c in categories" :key="c">{{c}}</option></select><label class="inline-check"><input v-model="archived" type="checkbox"/>{{t('显示已归档')}}</label></div>
 <p class="results-caption">{{t('套餐列表')}} <strong>{{filtered.length}}</strong><span>{{t('编辑权限与额度后，前往套餐上架设置销售。')}}</span></p><div class="plan-cards" :aria-busy="loading"><article v-for="p in filtered" :key="p.id" class="plan-card"><header><span class="plan-icon"><Package :size="21"/></span><div><h2>{{p.name}}</h2><small>{{p.category||t('未分类')}} · v{{p.version}}</small></div><span class="spacer"/><button class="icon" :aria-label="t('编辑套餐')+' '+p.name" @click="editPlan(p)"><Pencil :size="16"/></button><button v-if="!p.system" class="icon danger-icon" :aria-label="t('删除套餐')+' '+p.name" @click="deletePlan(p)"><Trash2 :size="16"/></button></header><p class="plan-description">{{p.description||t('尚未填写套餐简介')}}</p><div class="plan-value-grid"><div class="plan-price">{{money(p.price)}}<small>{{t('套餐价格')}}</small></div><div class="plan-quota">{{p.quota?bytes(p.quota):t('不限')}}<small>{{t('配额用量')}} · {{cycleLabel(p.cycle)}}</small></div></div><dl><div><dt>{{t('有效期')}}</dt><dd>{{p.valid_days?p.valid_days+' '+t('天'):t('不限')}}</dd></div><div><dt>{{t('节点权限组')}}</dt><dd>{{p.group_ids.length}}</dd></div><div><dt>{{t('单独节点')}}</dt><dd>{{p.node_ids?.length||0}}</dd></div></dl><button class="plan-assignments" @click="showMembers(p.id)"><ShieldCheck :size="15"/><span>{{assignedUsers(p.id).length}} {{t('位成员正在使用')}}<small v-if="assignedUsers(p.id).some(u=>u.entitlement?.version!==p.version)"> · {{t('包含历史版本权益')}}</small></span><ArrowUpRight :size="14"/></button><div class="plan-tags"><span v-if="p.vless" class="tag vless">VLESS</span><span v-if="p.hy2" class="tag hy2">HY2</span><span :class="['badge',p.archived?'neutral':'success']">{{p.archived?t('已归档'):t('可分配')}}</span></div><footer><span v-for="id in p.group_ids" :key="id">{{groups.find(g=>g.id===id)?.name||id}}<small v-if="selectedNodesInGroup(p,id).length"> · {{selectedNodesInGroup(p,id).length}} {{t('个单独节点')}}</small></span><span v-if="!p.group_ids.length">{{t('尚未配置节点权限')}}</span></footer></article></div><div v-if="!filtered.length" class="empty"><Package :size="28"/><h2>{{t(loaded?'暂无匹配套餐':'加载中…')}}</h2><p v-if="loaded">{{t(plans.length?'试试其他名称或筛选条件。':'暂无套餐，创建后可在用户管理中分配。')}}</p><button v-if="loaded&&(search||category||archived)" @click="search='';category='';archived=false">{{t('清除筛选')}}</button><button v-else-if="loaded&&!plans.length" class="primary" @click="editPlan()">{{t('创建套餐')}}</button></div></template>
 <template v-else-if="tab==='groups'"><div class="toolbar"><div class="search"><Search :size="16"/><input v-model="groupSearch" :placeholder="t('搜索节点、站点、协议或 IP')" :aria-label="t('搜索组内节点')"/></div><select v-model="groupSource" :aria-label="t('节点来源')"><option value="all">{{t('全部来源')}}</option><option value="local">{{t('本站节点')}}</option><option value="mounted">{{t('子站挂载')}}</option><option value="public">{{t('公共节点')}}</option></select></div><p class="field-help">{{t('节点按来源自动归组，无需手动分组。请在套餐管理中选择整组或组内节点。')}}</p><div class="plan-cards group-cards"><article v-for="g in filteredGroups" :key="g.id" class="plan-card"><header><span class="plan-icon" :class="'scope-'+g.scope"><Layers3 :size="21"/></span><div><h2>{{g.name}}</h2><small>{{t(g.scope==='subsite'?'子站挂载':g.scope==='public'?'公共节点':'本地节点')}}</small></div></header><p class="plan-description">{{g.description||t('尚未填写说明')}}</p><div class="plan-tags"><span :class="['badge',g.enabled?'success':'neutral']">{{g.enabled?t('已启用'):t('已停用')}}</span><span>{{groupRows(g.id).length}} {{t('个节点')}}</span></div><GroupNodeList :members="groupRows(g.id)"/><p v-if="!members[g.id]?.length" class="field-help">{{t('此组暂无节点，新增或挂载后会自动归组。')}}</p></article></div><div v-if="!filteredGroups.length" class="empty" role="status"><Layers3 :size="28"/><h2>{{t(loaded?'没有匹配的节点组':'加载中…')}}</h2><p v-if="loaded">{{t('试试其他名称或筛选条件。')}}</p><button v-if="groupSearch||groupSource!=='all'" @click="groupSearch='';groupSource='all'">{{t('清除筛选')}}</button></div></template>
 <section v-if="tab==='plans'&&workspace==='members'" class="admin-panel entitlement-snapshots"><div class="admin-section-heading"><div><h2>{{t('成员生效权益')}}</h2><p>{{t('当前套餐、到期时间和待恢复套餐以成员记录为准。')}}</p></div><select v-model="snapshotPlan" :aria-label="t('套餐筛选')"><option value="">{{t('全部套餐')}}</option><option v-for="p in plans" :key="p.id" :value="p.id">{{p.name}}</option></select></div><div class="admin-table-scroll"><table class="adaptive-table"><thead><tr><th>{{t('成员')}}</th><th>{{t('当前套餐')}}</th><th>{{t('模板版本')}}</th><th>{{t('有效期')}}</th><th>{{t('操作')}}</th></tr></thead><tbody><tr v-for="u in snapshotUsers" :key="u.id"><td :data-label="t('成员')"><strong>{{u.username}}</strong></td><td :data-label="t('当前套餐')"><strong>{{u.entitlement?.name}}</strong><small v-if="u.plan_queue?.length">{{u.plan_queue.length}} {{t('个套餐等待恢复')}}</small></td><td :data-label="t('模板版本')"><span class="badge" :class="currentVersion(u)===u.entitlement?.version?'success':'neutral'">v{{u.entitlement?.version}}</span><small v-if="currentVersion(u)&&currentVersion(u)!==u.entitlement?.version">{{t('最新模板')}} v{{currentVersion(u)}}</small></td><td :data-label="t('有效期')">{{u.expires?new Date(u.expires*1000).toLocaleDateString():t('不限')}}</td><td :data-label="t('操作')"><div v-if="!u.archived" class="admin-inline-actions"><button @click="entitlementUsers=[u]">{{t('调整权益')}}</button><button @click="showSub(u)">{{t('查看订阅')}}</button></div><span v-else class="muted">{{t('历史记录只读')}}</span></td></tr><tr v-if="!snapshotUsers.length"><td colspan="5" class="empty">{{t('暂无成员使用此套餐')}}</td></tr></tbody></table></div></section>
 <EntitlementDialog v-if="entitlementUsers.length" :users="entitlementUsers" @close="entitlementUsers=[]" @updated="entitlementUpdated"/>
 <Teleport to="body"><div v-if="open" class="modal-shade" @click.self="close"><form class="modal entitlement-editor" ref="dialog" tabindex="-1" role="dialog" aria-modal="true" :aria-label="t('套餐设置')" @submit.prevent="save"><div class="modal-head"><div><span class="eyebrow">PLAN EDITOR</span><h2>{{t(editingPlan?.id?'编辑套餐':'创建套餐')}}</h2></div><button type="button" class="icon" :disabled="busy" :aria-label="t('关闭')" @click="close"><X :size="20"/></button></div>
 <fieldset v-if="editingPlan" class="editor-fields" :disabled="busy"><p class="editor-intro"><ShieldCheck :size="16"/>{{t('保存后会立即同步当前生效成员；额度、到期时间和排队套餐快照保持不变。')}}</p><section class="editor-section"><h3><span>01</span>{{t('基本信息')}}</h3><label>{{t('套餐名称')}}<input v-model="editingPlan.name" maxlength="100" required/></label><div class="field-row"><label>{{t('套餐分类')}}<input v-model="editingPlan.category" list="plan-categories" maxlength="100"/><datalist id="plan-categories"><option v-for="c in categories" :key="c" :value="c"/></datalist></label><label>{{t('排序')}}<input v-model.number="editingPlan.sort" type="number" min="0" max="9999"/></label></div><label>{{t('套餐简介')}}<textarea v-model="editingPlan.description" maxlength="2000" rows="2"/></label></section><section class="editor-section"><h3><span>02</span>{{t('价格与有效期')}}</h3><label>{{t('套餐价格 / 元')}}<input v-model="priceYuan" inputmode="decimal" placeholder="0.00" required/><small>{{t('用于套餐目录和新销售配置，订单会保存价格快照')}}</small></label><div class="field-row"><label>{{t('周期额度 / GiB')}}<input v-model.number="quotaGB" :disabled="unlimited" type="number" min="0.0001" step="any" required/></label><label>{{t('有效天数')}}<input v-model.number="editingPlan.valid_days" type="number" min="0" max="36500" required/><small>{{t('0 为不限')}}</small></label></div><label class="inline-check"><input v-model="unlimited" type="checkbox"/>{{t('不限额度')}}</label><div class="field-row"><label>{{t('配额周期')}}<select v-model="editingPlan.cycle"><option value="none">{{t('不自动重置')}}</option><option value="30d">{{t('每 30 天')}}</option><option value="month">{{t('每自然月')}}</option></select></label><label v-if="editingPlan.cycle==='month'">{{t('周期时区')}}<select v-model="editingPlan.timezone"><option>Asia/Shanghai</option><option>UTC</option><option>America/New_York</option><option>Europe/London</option><option>Asia/Singapore</option></select></label></div></section><section class="editor-section"><h3><span>03</span>{{t('节点与协议')}}</h3><PlanNodeSelector :groups="groups" :members="members" :nodes="state?.nodes||[]" :group-ids="editingPlan.group_ids" :node-ids="editingPlan.node_ids"  @update:group-ids="editingPlan.group_ids=$event" @update:node-ids="editingPlan.node_ids=$event"/><div class="check-row"><label class="inline-check"><input v-model="editingPlan.vless" type="checkbox"/>VLESS</label><label class="inline-check"><input v-model="editingPlan.hy2" type="checkbox"/>HY2</label><label class="inline-check"><input v-model="editingPlan.archived" type="checkbox"/>{{t('归档套餐')}}</label></div></section><details class="editor-notes"><summary>{{t('管理员备注')}}</summary><label><span class="sr-only">{{t('管理员备注')}}</span><textarea v-model="editingPlan.notes" rows="2" maxlength="2000"/></label></details></fieldset>
 <div v-if="discardRequested&&editorDirty" ref="discardNotice" tabindex="-1" class="draft-warning" role="alert"><p>{{t('当前修改尚未保存，关闭后将丢失。')}}</p><div class="admin-inline-actions"><button type="button" @click="discardRequested=false">{{t('继续编辑')}}</button><button type="button" class="danger-button" @click="discardPlan">{{t('放弃修改并关闭')}}</button></div></div><p v-if="error" class="error" role="alert">{{t(error)}}</p><div class="modal-footer"><button type="button" :disabled="busy" @click="close">{{t('取消')}}</button><button class="primary" :disabled="busy">{{busy?t('保存中…'):t('保存设置')}}</button></div></form></div></Teleport>
</section>
